def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers, else False."""
    if a <= 1:
        return False

    n = a
    count = 0

    # Factor out 2
    while n % 2 == 0:
        n //= 2
        count += 1
        if count > 3:
            return False

    # Factor out odd primes
    divisor = 3
    while divisor * divisor <= n:
        while n % divisor == 0:
            n //= divisor
            count += 1
            if count > 3:
                return False
        divisor += 2

    # Remaining prime factor
    if n > 1:
        count += 1

    return count == 3

